@import url('https://fonts.googleapis.com/css2?family=Urbanist:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Pinterest DNA — pin red on gallery white, masonry softness */
.theme-pinterest-dna {
  --bg: oklch(1.000 0 0);
  --surface: oklch(0.973 0 0);
  --surface-2: oklch(0.943 0 0);
  --fg: oklch(0.227 0.021 322.6);
  --fg-muted: oklch(0.538 0 0);
  --accent: oklch(0.582 0.236 25.5);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.406 0.167 29.2);
  --line: oklch(0.922 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 1rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Urbanist", sans-serif;
  --font-body: "Urbanist", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.04em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-pinterest-dna h1,
.theme-pinterest-dna h2,
.theme-pinterest-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-pinterest-dna { --font-ui: var(--font-display); }
.theme-pinterest-dna h1 { font-weight: 700; }
.theme-pinterest-dna button:hover { transform: scale(1.03); }

/* depth */
.theme-pinterest-dna thead th { font-weight: 700; color: var(--fg); border-bottom: 2px solid var(--line); }
.theme-pinterest-dna td { border-bottom: 1px solid var(--line); }
.theme-pinterest-dna tbody tr:hover { background: var(--surface); }
.theme-pinterest-dna a { color: var(--fg); font-weight: 700; text-decoration: underline; text-underline-offset: 2px; }
.theme-pinterest-dna a:hover { color: var(--accent); }
.theme-pinterest-dna input, .theme-pinterest-dna select { background: var(--bg); border: 2px solid var(--line); border-radius: var(--radius-pill); }
.theme-pinterest-dna textarea { background: var(--bg); border: 2px solid var(--line); border-radius: var(--radius-lg); }
.theme-pinterest-dna input:focus-visible, .theme-pinterest-dna textarea:focus-visible, .theme-pinterest-dna select:focus-visible { outline: none; border-color: oklch(0.7 0.11 240); box-shadow: 0 0 0 2px oklch(0.7 0.11 240 / 45%); } /* Pinterest's blue focus halo */
.theme-pinterest-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface-2); border-radius: var(--radius-pill); padding: 0.1em 0.55em; }
.theme-pinterest-dna ::selection { background: oklch(0.9 0.05 25); }
.theme-pinterest-dna ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-pinterest-dna ::-webkit-scrollbar-track { background: transparent; }
.theme-pinterest-dna ::-webkit-scrollbar-thumb { background: oklch(0.8 0 0); border-radius: 5px; }
.theme-pinterest-dna img { border-radius: var(--radius); } /* every image is a pin */
.theme-pinterest-dna .label-caps { color: var(--fg-muted); font-weight: 600; }
.theme-pinterest-dna .themed-border { border-radius: var(--radius); transition: box-shadow 150ms; }
.theme-pinterest-dna .themed-border:hover { box-shadow: var(--shadow-2); } /* pin lift */
.theme-pinterest-dna button:active { transform: scale(0.94); }

/* alt mode: Pinterest dark — neutral gallery black, red stays saturated */
.theme-pinterest-dna.alt-mode {
  --bg: oklch(0.145 0.000 0.0);
  --surface: oklch(0.185 0.000 0.0);
  --surface-2: oklch(0.225 0.000 0.0);
  --accent: oklch(0.62 0.24 25.5);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
}
.theme-pinterest-dna.alt-mode ::selection { background: oklch(0.42 0.12 25); }
.theme-pinterest-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.4 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
